let mut beats = Vec::new();
let mut i = 0;
while i < music_string.len() {
    match music_string.as_bytes()[i] {
        b'o' => {
            if i + 1 < music_string.len() && music_string.as_bytes()[i + 1] == b'|' {
                beats.push(2);
                i += 2;
            } else {
                beats.push(4);
                i += 1;
            }
        }
        b'.' => {
            if i + 1 < music_string.len() && music_string.as_bytes()[i + 1] == b'|' {
                beats.push(1);
                i += 2;
            } else {
                i += 1;
            }
        }
        _ => {
            i += 1;
        }
    }
}
